#!/usr/bin/env python3
"""Generate colour tokens and verify normal-text contrast for every palette/mode."""
import json,pathlib,sys
ROOT=pathlib.Path(__file__).resolve().parents[1]
PALETTES=json.loads((ROOT/'frontend/src/palettes.json').read_text())
def luminance(hex_color):
    values=[int(hex_color[i:i+2],16)/255 for i in (1,3,5)]
    values=[v/12.92 if v<=.04045 else ((v+.055)/1.055)**2.4 for v in values]
    return sum(v*w for v,w in zip(values,(.2126,.7152,.0722)))
def contrast(a,b):
    lo,hi=sorted((luminance(a),luminance(b)));return (hi+.05)/(lo+.05)
lines=['/* Generated by scripts/generate-palettes.py. Keep Kumo controls; change colour tokens only. */']
ratios=[]
for name,palette in PALETTES.items():
    for mode in ('light','dark'):
        p=palette[mode];dark=mode=='dark'
        for foreground in ('text','muted','accent'):
            for background in ('surface','low','container','high','highest'):
                ratio=contrast(p[foreground],p[background]);ratios.append(ratio)
                if ratio<4.5:raise SystemExit(f'FAIL {name}/{mode}: {foreground} on {background} = {ratio:.2f}')
        for foreground,background in ((p['text'],p['highest']),(p['accentText'],p['accentBg']),('#ffffff',p['button']),('#ffffff',p['hover'])):
            ratio=contrast(foreground,background);ratios.append(ratio)
            if ratio<4.5:raise SystemExit(f'FAIL {name}/{mode}: {foreground}/{background} = {ratio:.2f}')
        tone=','.join(str(int(p['accent'][i:i+2],16)) for i in (1,3,5))
        tokens={'surface':p['surface'],'on-surface':p['text'],'on-surface-variant':p['muted'],'surface-container-lowest':p['low'],'surface-container-low':p['low'],'surface-container':p['container'],'surface-container-high':p['high'],'surface-container-highest':p['highest'],'primary':p['accent'],'on-primary':'#101318' if dark else '#ffffff','primary-container':p['accentBg'],'on-primary-container':p['accentText'],'secondary':p['muted'],'secondary-container':p['highest'],'on-secondary-container':p['text'],'tertiary':'#b3edc4' if dark else '#166534','tertiary-container':'#233d2b' if dark else '#dcf1e2','on-tertiary-container':'#d9f9e2' if dark else '#154d2c','outline':'#9aa6b8' if dark else '#7b8794','outline-variant':'#4e596b' if dark else '#d2d8e0','error':'#ffb4ab' if dark else '#a71919','on-error':'#ffffff','error-container':'#51251f' if dark else '#fce5e1','on-error-container':'#ffdad4' if dark else '#7b211a'}
        for foreground,background in ((tokens['error'],p['highest']),(tokens['tertiary'],p['highest']),(tokens['on-error-container'],tokens['error-container']),(tokens['on-tertiary-container'],tokens['tertiary-container']),('#ffffff','#a71919')):
            ratio=contrast(foreground,background);ratios.append(ratio)
            if ratio<4.5:raise SystemExit(f'FAIL {name}/{mode}: semantic text contrast {ratio:.2f}')
        lines.append(f'html[data-palette=kumo][data-color={name}][data-mode={mode}]'+'{')
        lines.extend(f'  --md-sys-color-{key}:{value};' for key,value in tokens.items())
        lines.append(f'  --kumo-brand:{p["button"]};--kumo-brand-hover:{p["hover"]};--action-bg:{p["button"]};--synapse-tone:{tone};')
        lines.append('}')
lines.extend(['html[data-palette=kumo][data-color] .send{background:var(--action-bg);color:#fff}', 'html[data-palette=kumo][data-color] .send:hover:not(:disabled){background:var(--kumo-brand-hover)}','html[data-palette=kumo][data-color] .send.danger{background:#a71919;color:#fff}','html[data-palette=kumo][data-color] .send.danger:hover:not(:disabled){background:#851414}','html[data-palette=kumo][data-color] input::placeholder,html[data-palette=kumo][data-color] textarea::placeholder{color:var(--md-sys-color-on-surface-variant);opacity:1}'])
lines.extend(['html[data-palette=kumo][data-color] nav.chat-list button small{opacity:1}','html[data-palette=kumo][data-color] table.usage tr.off td{opacity:1;color:var(--md-sys-color-on-surface-variant)}','html[data-palette=kumo][data-color] .perm-off code{opacity:1;color:var(--md-sys-color-on-surface-variant)}','html[data-palette=kumo][data-color] .limits-badge.refreshing{opacity:1}'])
output='\n'.join(lines)+'\n';target=ROOT/'frontend/src/ColorPalettes.css'
if '--check' in sys.argv:
    if not target.exists() or target.read_text()!=output:raise SystemExit('FAIL: generated CSS is out of date')
else:target.write_text(output)
print(f'PASS: {len(PALETTES)} palettes, 2 modes, {len(ratios)} normal-text pairs, minimum contrast {min(ratios):.2f}:1')
